cat > bot.mjs <<'EOF'
// SMS send gate. Decides only; never sends. Nothing is stored between calls.
// Marketing: needs opt-in, no recorded STOP, valid recipient time zone, and recipient-local
// calling hours (47 CFR 64.1200(c)(1): 08:00 to before 21:00; India (TRAI) 09:00 to before 21:00).
// Transactional: not held by consent, STOP record or hours (asked-for / order updates).

const US_START = "08:00";
const IN_START = "09:00";
const END = "21:00";

function hold(rule) {
  return { allowed: false, rule };
}

export async function checkSend({ user, message, now } = {}) {
  try {
    if (message === null || typeof message !== "object") return hold("invalid-message");
    if (typeof message.text !== "string" || message.text.trim() === "") return hold("empty-text");
    // Anything that is not exactly "transactional" is marketing.
    const transactional = message.kind === "transactional";
    if (user === null || typeof user !== "object") return hold("invalid-user");
    if (transactional) return { allowed: true, rule: "" };

    const sms = user.sms;
    if (sms === null || typeof sms !== "object") return hold("no-consent");
    if (sms.optedOutAt !== null) {
      // A recorded STOP, or an optedOutAt we cannot read as "none": hold.
      return hold(sms.optedOutAt === undefined ? "no-consent" : "opted-out");
    }
    if (sms.optedIn !== true) return hold("no-consent");

    const ms = now instanceof Date ? now.getTime() : NaN;
    if (!Number.isFinite(ms)) return hold("invalid-time");
    const zone = user.timeZone;
    if (typeof zone !== "string" || zone.trim() === "" || !gkZoneOk(zone)) return hold("unknown-time-zone");
    const start = zone === "Asia/Kolkata" || zone === "Asia/Calcutta" ? IN_START : US_START;
    if (!gkInWindow(ms, zone, start, END)) return hold("outside-calling-hours");
    return { allowed: true, rule: "" };
  } catch {
    return hold("check-failed");
  }
}
EOF
